hints.test:
assert.isFalse(
  confirmEnding(
    'Walking on water and developing software from a specification are easy if both are frozen',
    'specification'
  )
);

assert.isFalse(
  confirmEnding(
    "If you want to save our world, you must hurry. We don't know how much longer we can withstand the nothing",
    'mountain'
  )
);

const endsWithSpy = __helpers.spyOn(String.prototype, 'endsWith');
try {
  confirmEnding('Bastian', 'n');
  confirmEnding('Connor', 'n');
  confirmEnding('Open sesame', 'game');
  assert.isEmpty(endsWithSpy.calls);
} finally {
  endsWithSpy.restore();
}

items.solution:
function confirmEnding(str, target) {
  return str.substring(str.length - target.length) === target;
}

confirmEnding('Bastian', 'n');
